css:
.energizesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1b232e;
    background: linear-gradient(160deg, #eef1f6 0%, #e4e9f1 100%);
    border-radius: 18px;
}

.energizesim-container * {
    box-sizing: border-box;
}

.energizesim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #16202e 0%, #243650 55%, #2f4d6e 100%);
    color: #f4f7fb;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(22, 32, 46, 0.32);
    position: relative;
    overflow: hidden;
}

.energizesim-header::after {
    content: "";
    position: absolute;
    top: 0; right: 0;
    width: 180px; height: 100%;
    background: linear-gradient(105deg, transparent 0%, rgba(255, 196, 61, 0.16) 60%, rgba(255, 196, 61, 0.28) 100%);
    pointer-events: none;
}

.energizesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.energizesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffd27a;
    background: rgba(255, 255, 255, 0.10);
    padding: 5px 14px;
    border-radius: 999px;
}

.energizesim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dde6f1;
    position: relative;
    z-index: 1;
}

.energizesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2c3e57;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.energizesim-period-counter #currentDay,
.energizesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #16202e;
}

.energizesim-round-name {
    background: #d7e0ee;
    color: #243650;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.energizesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a4112;
    background: #fde9d4;
    padding: 4px 12px;
    border-radius: 999px;
}

.energizesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.energizesim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d6deea;
    box-shadow: 0 4px 14px rgba(22, 32, 46, 0.06);
    border-top: 4px solid #2f4d6e;
}

.energizesim-card-productive { border-top-color: #1f9d6b; }
.energizesim-card-corrosive { border-top-color: #c0392b; }
.energizesim-card-attrition { border-top-color: #c98a16; }
.energizesim-card-wellbeing { border-top-color: #2f6fb0; }

.energizesim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #647689;
}

.energizesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #16202e;
}

.energizesim-card-productive .energizesim-value { color: #1f9d6b; }
.energizesim-card-corrosive .energizesim-value { color: #c0392b; }
.energizesim-card-attrition .energizesim-value { color: #c98a16; }
.energizesim-card-wellbeing .energizesim-value { color: #2f6fb0; }

.energizesim-sublabel {
    font-size: 0.76rem;
    color: #7488a0;
    line-height: 1.35;
}

/* Productive energy state colouring vs the board exit threshold. */
.energizesim-productive-pass .energizesim-value { color: #1f9d6b; }
.energizesim-productive-fail .energizesim-value { color: #c0392b; }

/* Corrosive: green when below the healthy benchmark, red when high. */
.energizesim-corrosive-healthy .energizesim-value { color: #1f9d6b; }
.energizesim-corrosive-high .energizesim-value { color: #c0392b; }

.energizesim-attrition-pass .energizesim-value { color: #1f9d6b; }
.energizesim-attrition-fail .energizesim-value { color: #c0392b; }

.energizesim-wellbeing-cut .energizesim-value { color: #c0392b; }

.energizesim-meters {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
    margin-bottom: 18px;
}

.energizesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #16202e;
    color: #eaf1f9;
    padding: 10px 18px;
    border-radius: 12px;
    font-weight: 700;
    font-size: 0.9rem;
}

.energizesim-token-bar {
    background: #2f4d6e;
}

.energizesim-budget-bar #spendDisplay,
.energizesim-budget-bar #tokenDisplay {
    font-size: 1.02rem;
    letter-spacing: 0.3px;
    color: #ffd27a;
}

.energizesim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #2f4d6e;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(22, 32, 46, 0.05);
}

.energizesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.energizesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #16202e;
    margin-bottom: 6px;
}

.energizesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2f3e51;
}

.energizesim-briefing-text strong { color: #1f9d6b; }
.energizesim-briefing-text em { color: #9a4112; font-style: italic; }

.energizesim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d6deea;
    box-shadow: 0 4px 14px rgba(22, 32, 46, 0.06);
}

.energizesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #16202e;
    border-bottom: 2px solid #e4e9f1;
    padding-bottom: 8px;
}

.energizesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #243650;
    margin: 14px 0 6px;
}

.energizesim-container select,
.energizesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #b6c5d8;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f6f9fc;
    color: #1b232e;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.energizesim-container select:focus,
.energizesim-container input[type="number"]:focus {
    outline: none;
    border-color: #2f6fb0;
    box-shadow: 0 0 0 3px rgba(47, 111, 176, 0.16);
}

.energizesim-container select option {
    background-color: #ffffff;
    color: #1b232e;
}

.energizesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2f6fb0;
}

.energizesim-range-readout,
.energizesim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2c3e57;
    margin-top: 4px;
}

.energizesim-range-readout span:last-child,
.energizesim-alloc-readout span:nth-child(2) {
    color: #1f9d6b;
    font-weight: 800;
}

.energizesim-hint {
    font-size: 0.8rem;
    color: #7488a0;
    margin-top: 4px;
    line-height: 1.4;
}

.energizesim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.energizesim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f2f6fb;
    border: 1px solid #dbe5f0;
    border-radius: 9px;
    padding: 8px 12px;
}

.energizesim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #243650;
}

.energizesim-alloc-row input[type="number"] {
    width: 80px;
    flex: 0 0 80px;
}

.energizesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.energizesim-container .btn-primary {
    background: linear-gradient(135deg, #1f9d6b 0%, #2f6fb0 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(31, 157, 107, 0.26);
}

.energizesim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.energizesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #b6c5d8;
    color: #647689;
}

.energizesim-coach {
    background: #16202e;
    color: #eaf1f9;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(22, 32, 46, 0.24);
    border-left: 5px solid #ffc43d;
}

.energizesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffd27a;
    margin-bottom: 8px;
}

.energizesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.energizesim-coach-body strong { color: #8fe3bd; }
.energizesim-coach-body em { color: #ffc1ad; font-style: italic; }

.energizesim-history,
.energizesim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d6deea;
    box-shadow: 0 4px 14px rgba(22, 32, 46, 0.06);
}

.energizesim-history h3,
.energizesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #16202e;
}

.energizesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #243650;
}

.energizesim-container table#usfHistoryTable th {
    background: #eaeff6;
    color: #16202e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d4dded;
}

.energizesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef2f7;
}

.energizesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7fafd;
}

.energizesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .energizesim-container {
        padding: 14px;
    }
    .energizesim-header h1 {
        font-size: 1.7rem;
    }
    .energizesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .energizesim-value {
        font-size: 2rem;
    }
    .energizesim-clock {
        margin-left: 0;
    }
    .energizesim-period-counter {
        font-size: 0.88rem;
    }
    .energizesim-meters {
        grid-template-columns: 1fr;
    }
    .energizesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .energizesim-alloc-row {
        flex-wrap: wrap;
    }
    .energizesim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .energizesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion message (formatCompletionMessage) */
.energizesim-completion { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1b232e; }
.energizesim-cm-head { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; padding-bottom: 14px; border-bottom: 1px solid rgba(22,32,46,0.12); margin-bottom: 16px; }
.energizesim-cm-score { font-size: 46px; font-weight: 800; line-height: 1; color: #1f9d6b; }
.energizesim-cm-score-max { font-size: 18px; font-weight: 600; color: #647689; margin-left: 2px; }
.energizesim-cm-grade { font-size: 18px; font-weight: 700; color: #1b232e; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.energizesim-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; letter-spacing: .02em; padding: 3px 10px; border-radius: 999px; }
.energizesim-cm-yes { background: rgba(31,157,107,0.14); color: #157a52; }
.energizesim-cm-no { background: rgba(192,57,43,0.12); color: #b03325; }
.energizesim-cm-warn { background: rgba(214,158,46,0.16); color: #9a6b12; }
.energizesim-cm-metrics { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 18px; }
.energizesim-cm-metric { flex: 1 1 120px; background: #f4f7f9; border: 1px solid rgba(22,32,46,0.08); border-radius: 10px; padding: 12px 14px; text-align: center; }
.energizesim-cm-mv { display: block; font-size: 24px; font-weight: 800; color: #1b232e; }
.energizesim-cm-ml { display: block; font-size: 12px; font-weight: 600; color: #647689; margin-top: 2px; }
.energizesim-cm-insights-title { font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: #647689; margin-bottom: 8px; }
.energizesim-cm-insights { margin: 0; padding-left: 20px; }
.energizesim-cm-insights li { font-size: 14px; line-height: 1.5; color: #33414f; margin-bottom: 8px; }

