(function() {
    'use strict';

    class EnergizeAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Energize the Org`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.START_PRODUCTIVE = 38;     // healthy ≈ 65
            this.START_CORROSIVE = 16;      // healthy < 8
            this.START_RESIGNED = 24;
            this.START_COMFORTABLE = 22;
            this.START_ATTRITION = 18;      // firm avg 7
            this.START_ENGAGEMENT = 58;     // was 74
            this.TARGET_PRODUCTIVE = 55;    // board exit floor
            this.TARGET_ATTRITION = 12;     // board exit ceiling
            this.HEALTHY_PRODUCTIVE = 65;
            this.HEALTHY_CORROSIVE = 8;
            this.SPEND_CAP = 240;           // CHF 240k discretionary, in thousands
            this.TOKEN_CAP = 20;            // 20 leadership focus tokens
            this.WELLBEING_START = 1.10;    // CHF millions
            this.WELLBEING_CUT = 0.44;      // 40% of 1.1M

            // Hidden capacities (trust must precede mobilisation; recovery prevents the acceleration trap).
            this.START_TRUST = 24;
            this.START_RECOVERY = 20;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    productive: this.START_PRODUCTIVE,
                    corrosive: this.START_CORROSIVE,
                    resigned: this.START_RESIGNED,
                    comfortable: this.START_COMFORTABLE,
                    attrition: this.START_ATTRITION,
                    engagement: this.START_ENGAGEMENT,
                    trust: this.START_TRUST,
                    recovery: this.START_RECOVERY,
                    spendUsed: 0,
                    tokensUsed: 0,
                    wellbeing: this.WELLBEING_START,
                    accelerationTrap: false,
                    merged: false,
                    productiveHistory: [this.START_PRODUCTIVE],
                    corrosiveHistory: [this.START_CORROSIVE],
                    resignedHistory: [this.START_RESIGNED],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    dominant: `corrosive`,
                    production: `resigned`,
                    driver: `leadership`,
                    focus: 60,
                    first: `triage`,
                    tokTriage: 7,
                    tokCoalition: 7,
                    tokRecognition: 4,
                    tokCoaching: 2,
                    recogSpend: 30,
                    hybrid: `keepfour`,
                    budget: `protect`,
                    caseRigor: 60,
                    triageSpend: 40,
                    recovery: `stopdoing`,
                    indicator: `energy`,
                    pitch: `healthy`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const dom = document.getElementById(`dominantInput`);
                const prod = document.getElementById(`productionInput`);
                const drv = document.getElementById(`driverInput`);
                const foc = document.getElementById(`focusInput`);
                if (dom) decisions.dominant = dom.value;
                if (prod) decisions.production = prod.value;
                if (drv) decisions.driver = drv.value;
                if (foc) decisions.focus = parseInt(foc.value, 10);
                if (!Number.isFinite(decisions.focus) || decisions.focus < 0 || decisions.focus > 100) {
                    warn(`warn_focus_range`); return false;
                }
            } else if (round === 2) {
                const first = document.getElementById(`firstInput`);
                if (first) decisions.first = first.value;
                const ids = [[`tokTriageInput`, `tokTriage`], [`tokCoalitionInput`, `tokCoalition`], [`tokRecognitionInput`, `tokRecognition`], [`tokCoachingInput`, `tokCoaching`]];
                ids.forEach((pair) => {
                    const el = document.getElementById(pair[0]);
                    if (el) decisions[pair[1]] = parseInt(el.value, 10);
                });
                const toks = [decisions.tokTriage, decisions.tokCoalition, decisions.tokRecognition, decisions.tokCoaching];
                if (toks.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_token_negative`); return false;
                }
                const totalTok = toks.reduce((a, b) => a + b, 0);
                if (totalTok !== this.TOKEN_CAP) {
                    warn(`warn_token_total`); return false;
                }
                const rs = document.getElementById(`recogSpendInput`);
                if (rs) decisions.recogSpend = parseFloat(rs.value);
                if (!Number.isFinite(decisions.recogSpend) || decisions.recogSpend < 0) {
                    warn(`warn_recog_negative`); return false;
                }
            } else if (round === 3) {
                const hy = document.getElementById(`hybridInput`);
                const bu = document.getElementById(`budgetInput`);
                const ca = document.getElementById(`caseInput`);
                const ts = document.getElementById(`triageSpendInput`);
                if (hy) decisions.hybrid = hy.value;
                if (bu) decisions.budget = bu.value;
                if (ca) decisions.caseRigor = parseInt(ca.value, 10);
                if (ts) decisions.triageSpend = parseFloat(ts.value);
                if (!Number.isFinite(decisions.caseRigor) || decisions.caseRigor < 0 || decisions.caseRigor > 100) {
                    warn(`warn_case_range`); return false;
                }
                if (!Number.isFinite(decisions.triageSpend) || decisions.triageSpend < 0) {
                    warn(`warn_triage_negative`); return false;
                }
            } else if (round === 4) {
                const re = document.getElementById(`recoveryInput`);
                const ind = document.getElementById(`indicatorInput`);
                const pi = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (re) decisions.recovery = re.value;
                if (ind) decisions.indicator = ind.value;
                if (pi) decisions.pitch = pi.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas accumulate across the four energy states + capacities.
            let prodDelta = 0, corrDelta = 0, resigDelta = 0;
            let attrDelta = 0, engDelta = 0, trustDelta = 0, recovDelta = 0;
            let spend = 0, tokens = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: read quality AND intensity before acting (Common Error 1).
                if (d.dominant === `corrosive`) {
                    trustDelta += 6; prodDelta += 3; coachKey = `coach_r1_dom_right`;
                } else if (d.dominant === `resigned`) {
                    trustDelta += 1; coachKey = `coach_r1_dom_resigned`;
                } else if (d.dominant === `comfortable`) {
                    prodDelta -= 3; coachKey = `coach_r1_dom_comfortable`;
                } else {
                    prodDelta -= 5; corrDelta += 2; coachKey = `coach_r1_dom_lazy`;
                }

                // The production sub-team is RESIGNED, not corrosive: confront it and you push it out.
                if (d.production === `resigned`) {
                    resigDelta -= 5; prodDelta += 4; trustDelta += 4;
                    if (d.dominant === `corrosive`) coachKey = `coach_r1_diag_sharp`;
                } else if (d.production === `corrosive`) {
                    resigDelta += 4; attrDelta += 2; trustDelta -= 4; coachKey = `coach_r1_confront`;
                } else {
                    resigDelta += 2; coachKey = `coach_r1_prod_fine`;
                }

                // Root driver: the leadership vacuum + coalition is the real cause.
                if (d.driver === `leadership`) {
                    trustDelta += 4; prodDelta += 2;
                } else if (d.driver === `overload`) {
                    prodDelta += 1;
                } else if (d.driver === `pay`) {
                    trustDelta -= 3; coachKey = `coach_r1_pay`;
                } else {
                    trustDelta -= 4; corrDelta += 1; coachKey = `coach_r1_fourday`;
                }

                // Focus: concentrate the first move on the corrosive coalition, do not spread thin (Common Error 6).
                if (d.focus >= 60) {
                    corrDelta -= 3; prodDelta += 3;
                } else if (d.focus <= 30) {
                    corrDelta += 2; prodDelta -= 2; coachKey = `coach_r1_evenfocus`;
                }

                summaryKey = (d.dominant === `corrosive` && d.production === `resigned` && d.driver === `leadership`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Choose the intervention portfolio + sequence (Common Errors 2 & 6).
                tokens = d.tokTriage + d.tokCoalition + d.tokRecognition + d.tokCoaching;

                // FIRST move = sequencing. Trust-building must precede mobilisation.
                // A motivational kickoff while trust is low inflames corrosive energy.
                const trustNow = ds.trust;
                switch (d.first) {
                    case `triage`:
                        spend += 40; prodDelta += 9; resigDelta -= 4; recovDelta += 6; trustDelta += 5; coachKey = `coach_r2_triage`;
                        break;
                    case `coalition`:
                        spend += 30; corrDelta -= 7; trustDelta += 6; prodDelta += 3; recovDelta += 6; coachKey = `coach_r2_coalition`;
                        break;
                    case `kickoff`:
                        spend += 60;
                        if (trustNow < 45) {
                            // Premature rally: cynicism rises (16% → ~21% in the concept).
                            corrDelta += 6; trustDelta -= 4; prodDelta += 1; coachKey = `coach_r2_kickoff_early`;
                        } else {
                            prodDelta += 7; corrDelta -= 1; coachKey = `coach_r2_kickoff_ok`;
                        }
                        break;
                    case `backfill`:
                        spend += 90; attrDelta -= 2; prodDelta += 3; recovDelta += 2; coachKey = `coach_r2_backfill`;
                        break;
                }

                // Token concentration. The corrosive coalition sits in ONE sub-team; even splits are
                // fair but ineffective. Reward leaning into triage + coalition (the high-leverage pair).
                const maxTok = Math.max(d.tokTriage, d.tokCoalition, d.tokRecognition, d.tokCoaching);
                const evenSplit = maxTok <= 6; // ~5 each across four = diffuse attention
                const leverage = d.tokTriage + d.tokCoalition; // the two highest-leverage levers
                if (evenSplit) {
                    prodDelta -= 4; corrDelta += 2; coachKey = `coach_r2_eventokens`;
                } else if (leverage >= 12 && d.tokCoalition >= 5 && d.tokTriage >= 5) {
                    prodDelta += 7; corrDelta -= 4; trustDelta += 3; coachKey = `coach_r2_concentrated`;
                } else if (d.tokCoaching >= 10 && trustNow < 45) {
                    prodDelta += 1; coachKey = `coach_r2_coachingheavy`;
                } else {
                    prodDelta += 3; corrDelta -= 1;
                }

                // Recognition & small-wins spend builds trust cheaply — IF the coalition is being handled.
                spend += d.recogSpend;
                if (d.recogSpend >= 20) {
                    trustDelta += 6; resigDelta -= 3;
                    if (d.tokCoalition < 3 && ds.corrosive > 12) { trustDelta -= 3; coachKey = `coach_r2_recognition_alone`; }
                } else if (d.recogSpend > 0) {
                    trustDelta += 2;
                }

                summaryKey = (d.first !== `kickoff` && !evenSplit && leverage >= 12) ? `sum_r2_good` : (d.first === `kickoff` && trustNow < 45 ? `sum_r2_inflame` : `sum_r2_weak`);
            } else if (round === 3) {
                // Hybrid policy + defend the wellbeing budget (Common Errors 3 & 4).
                // Presence policy signals trust; five-days-on-site buys short velocity, costs autonomy.
                switch (d.hybrid) {
                    case `keepfour`:
                        prodDelta += 8; trustDelta += 6; attrDelta -= 3; coachKey = `coach_r3_keepfour`;
                        break;
                    case `flexhybrid`:
                        prodDelta += 6; trustDelta += 4; attrDelta -= 2; coachKey = `coach_r3_flexhybrid`;
                        break;
                    case `coredays`:
                        prodDelta += 2; trustDelta -= 2; attrDelta += 1; coachKey = `coach_r3_coredays`;
                        break;
                    case `fivedays`:
                        // Short-term coordination gain, long-term attrition spike (3 more resign → ~22%).
                        prodDelta += 3; trustDelta -= 8; attrDelta += 6; corrDelta += 2; coachKey = `coach_r3_fivedays`;
                        break;
                }

                // Wellbeing budget. Cutting it to protect EBIT ignores CHF 95k-per-engineer attrition cost.
                switch (d.budget) {
                    case `protect`:
                        ds.wellbeing = this.WELLBEING_START;
                        attrDelta -= 4; trustDelta += 5; recovDelta += 5; coachKey = (d.hybrid === `keepfour`) ? `coach_r3_protect` : coachKey;
                        break;
                    case `reallocate`:
                        ds.wellbeing = this.WELLBEING_START;
                        attrDelta -= 2; recovDelta += 6; prodDelta += 2; trustDelta += 2;
                        break;
                    case `cut`:
                        ds.wellbeing = this.WELLBEING_START - this.WELLBEING_CUT;
                        attrDelta += 7; recovDelta -= 6; trustDelta -= 6; prodDelta -= 3; coachKey = `coach_r3_cut`;
                        break;
                }

                // Business-case rigour. A defended budget only lands if argued in board language.
                if (d.budget !== `cut`) {
                    if (d.caseRigor >= 60) { attrDelta -= 2; engDelta += 2; }
                    else if (d.caseRigor <= 25) { attrDelta += 2; coachKey = `coach_r3_weakcase`; }
                }

                // Deepening workload triage = the JD-R resource that converts effort into productive energy.
                spend += d.triageSpend;
                if (d.triageSpend >= 30) { prodDelta += 6; recovDelta += 5; }
                else if (d.triageSpend >= 10) { prodDelta += 3; recovDelta += 2; }
                else { prodDelta -= 2; recovDelta -= 3; coachKey = `coach_r3_notriage`; }

                summaryKey = (d.hybrid !== `fivedays` && d.budget !== `cut`) ? `sum_r3_good` : (d.hybrid === `fivedays` ? `sum_r3_autonomy` : `sum_r3_cut`);
            } else if (round === 4) {
                // Lock in healthy high performance: recovery guardrails beat borrowed effort (Common Error 5).
                switch (d.recovery) {
                    case `stopdoing`:
                        recovDelta += 14; prodDelta += 7; engDelta += 4; coachKey = `coach_r4_stopdoing`;
                        break;
                    case `recovery`:
                        recovDelta += 9; prodDelta += 4; coachKey = `coach_r4_recovery`;
                        break;
                    case `stack`:
                        // The acceleration trap: more initiatives on a 9-hour overtime base.
                        recovDelta -= 10; prodDelta += 2; corrDelta += 3; attrDelta += 3; coachKey = `coach_r4_stack`;
                        break;
                    case `ignore`:
                        recovDelta -= 8; attrDelta += 4; coachKey = `coach_r4_ignore`;
                        break;
                }

                // Leading indicator: a renewable-energy read warns before relapse; lagging-only is too slow.
                switch (d.indicator) {
                    case `energy`:
                        recovDelta += 5; prodDelta += 3; break;
                    case `velocity`:
                        recovDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r4_velocity` : coachKey; break;
                    case `attrition`:
                        recovDelta -= 1; break;
                }

                // Board pitch framing.
                switch (d.pitch) {
                    case `healthy`:
                        prodDelta += 6; trustDelta += 4; coachKey = (d.recovery === `stopdoing`) ? `coach_r4_healthy` : coachKey; break;
                    case `numbers`:
                        recovDelta -= 6; corrDelta += 1; coachKey = `coach_r4_numbers`; break;
                    case `victory`:
                        prodDelta -= 4; corrDelta += 3; trustDelta -= 3; coachKey = `coach_r4_victory`; break;
                }

                // Conviction nudges trust/productive.
                const convAdj = Math.round((d.conviction - 60) / 10);
                trustDelta += convAdj; prodDelta += Math.max(0, convAdj);

                summaryKey = (d.recovery === `stopdoing` || d.recovery === `recovery`) && d.pitch === `healthy` ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply capacities first (they gate the energy effects) ----
            ds.trust = Math.max(0, Math.min(100, ds.trust + trustDelta));
            ds.recovery = Math.max(0, Math.min(100, ds.recovery + recovDelta));

            // Resource accounting.
            ds.spendUsed = Math.min(this.SPEND_CAP, Math.round(ds.spendUsed + spend));
            ds.tokensUsed = Math.min(this.TOKEN_CAP, ds.tokensUsed + tokens);

            // Productive energy gains are dampened when recovery is low (the acceleration trap):
            // effort that is not renewable converts poorly into durable productive energy.
            let prodApplied = prodDelta;
            if (prodDelta > 0 && ds.recovery < 35) {
                prodApplied = prodDelta * 0.55; // borrowed effort, heavily discounted
            } else if (prodDelta > 0 && ds.recovery < 55) {
                prodApplied = prodDelta * 0.8;
            }

            ds.productive = Math.max(0, Math.min(100, ds.productive + prodApplied));
            ds.corrosive = Math.max(0, Math.min(100, ds.corrosive + corrDelta));
            ds.resigned = Math.max(0, Math.min(100, ds.resigned + resigDelta));
            // Comfortable energy drifts down as resigned/corrosive convert to productive.
            ds.comfortable = Math.max(0, Math.min(100, ds.comfortable - Math.round((prodApplied * 0.2))));
            // Attrition moves on its delta but is also eased by lower corrosive + higher trust.
            const corrosiveDrag = ds.corrosive > this.HEALTHY_CORROSIVE ? 0.6 : 0;
            ds.attrition = Math.max(4, Math.min(30, ds.attrition + attrDelta + corrosiveDrag - (trustDelta > 0 ? 0.4 : 0)));
            ds.engagement = Math.max(0, Math.min(100, ds.engagement + engDelta + Math.round(prodApplied * 0.3)));

            // Acceleration-trap flag: productive looks healthy but recovery is dangerously low.
            if (round === this.ROUNDS.length && ds.productive >= this.TARGET_PRODUCTIVE && ds.recovery < 40) {
                ds.accelerationTrap = true;
            }
            // Board merge flag at the final review.
            if (round === this.ROUNDS.length && (ds.productive < this.TARGET_PRODUCTIVE || ds.attrition > this.TARGET_ATTRITION)) {
                ds.merged = true;
            }

            ds.productiveHistory.push(Math.round(ds.productive));
            ds.corrosiveHistory.push(Math.round(ds.corrosive));
            ds.resignedHistory.push(Math.round(ds.resigned));

            // v1.1.0: publish the composite (0-100) to the reporting/grading layer
            // every period so express_resolveDomainScore reads a score and the trend fills.
            ds.performance = { overallScore: this._composite(ds) };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                productive: Math.round(ds.productive),
                productiveDelta: Math.round(prodApplied),
                corrosive: Math.round(ds.corrosive),
                corrosiveDelta: Math.round(corrDelta),
                resigned: Math.round(ds.resigned),
                attrition: Math.round(ds.attrition),
                attritionDelta: Math.round(attrDelta),
                trust: Math.round(ds.trust),
                recovery: Math.round(ds.recovery),
                spendUsed: ds.spendUsed,
                tokensUsed: ds.tokensUsed,
                wellbeing: ds.wellbeing,
                accelerationTrap: ds.accelerationTrap,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            uiManager.bind(`productiveDisplay`, `domainState.productive`, (v) => {
                const card = document.querySelector(`.energizesim-card-productive`);
                if (card) {
                    card.classList.toggle(`energizesim-productive-pass`, Number(v) >= this.TARGET_PRODUCTIVE);
                    card.classList.toggle(`energizesim-productive-fail`, Number(v) < this.TARGET_PRODUCTIVE);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`corrosiveDisplay`, `domainState.corrosive`, (v) => {
                const card = document.querySelector(`.energizesim-card-corrosive`);
                if (card) {
                    card.classList.toggle(`energizesim-corrosive-healthy`, Number(v) < this.HEALTHY_CORROSIVE);
                    card.classList.toggle(`energizesim-corrosive-high`, Number(v) >= this.HEALTHY_CORROSIVE);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`attritionDisplay`, `domainState.attrition`, (v) => {
                const card = document.querySelector(`.energizesim-card-attrition`);
                if (card) {
                    card.classList.toggle(`energizesim-attrition-pass`, Number(v) <= this.TARGET_ATTRITION);
                    card.classList.toggle(`energizesim-attrition-fail`, Number(v) > this.TARGET_ATTRITION);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`wellbeingDisplay`, `domainState.wellbeing`, (v) => {
                const card = document.querySelector(`.energizesim-card-wellbeing`);
                if (card) card.classList.toggle(`energizesim-wellbeing-cut`, Number(v) < this.WELLBEING_START - 0.001);
                return `CHF ` + Number(v).toFixed(2) + `M`;
            });

            uiManager.bind(`spendDisplay`, `domainState.spendUsed`, (v) => `CHF ` + Math.round(Number(v)) + `k / CHF 240k`);
            uiManager.bind(`tokenDisplay`, `domainState.tokensUsed`, (v) => Math.round(Number(v)) + ` / 20`);

            const self = this;

            // Round 1 focus slider readout.
            const foc = document.getElementById(`focusInput`);
            const focReadout = document.getElementById(`focusReadout`);
            if (foc && focReadout) {
                focReadout.textContent = foc.value;
                foc.addEventListener(`input`, function() { focReadout.textContent = foc.value; });
            }

            // Round 3 case-rigour slider readout.
            const ca = document.getElementById(`caseInput`);
            const caReadout = document.getElementById(`caseReadout`);
            if (ca && caReadout) {
                caReadout.textContent = ca.value;
                ca.addEventListener(`input`, function() { caReadout.textContent = ca.value; });
            }

            // Round 2 focus-token live total.
            const tokIds = [`tokTriageInput`, `tokCoalitionInput`, `tokRecognitionInput`, `tokCoachingInput`];
            const tokReadout = document.getElementById(`tokenAllocReadout`);
            const recompute = function() {
                let total = 0;
                tokIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseInt(el.value, 10) || 0);
                });
                if (tokReadout) tokReadout.textContent = total;
                const bar = document.querySelector(`.energizesim-alloc-readout`);
                if (bar) bar.style.color = (total !== self.TOKEN_CAP) ? `#c0392b` : ``;
            };
            tokIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        getChartConfig() {
            return {
                energyChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._cl(`legend_productive`, `Productive Energy %`),
                                data: [],
                                borderColor: `#1f9d6b`,
                                backgroundColor: `rgba(31,157,107,0.14)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#1f9d6b`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_corrosive`, `Corrosive Energy %`),
                                data: [],
                                borderColor: `#c0392b`,
                                backgroundColor: `rgba(192,57,43,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#c0392b`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_resigned`, `Resigned Inertia %`),
                                data: [],
                                borderColor: `#7488a0`,
                                backgroundColor: `rgba(116,136,160,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#7488a0`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#1b232e`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 80, position: `left`,
                                ticks: { color: `#647689` }, grid: { color: `rgba(22,32,46,0.08)` },
                                title: { display: true, text: `% of unit energy`, color: `#647689` }
                            },
                            x: {
                                ticks: { color: `#647689` }, grid: { color: `rgba(22,32,46,0.06)` },
                                title: { display: true, text: `Quarter`, color: `#647689` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.productiveHistory.map((_, i) => (i === 0 ? `Start` : `Q` + i));
            return {
                energyChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.productiveHistory },
                        { data: ds.corrosiveHistory },
                        { data: ds.resignedHistory }
                    ]
                }
            };
        }

        // Shared composite (0-100). Written to domainState.performance.overallScore each period
        // for the reporting/grading layer. Weights copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            var productive = Math.round(ds.productive || 0);
            var corrosive = Math.round(ds.corrosive || 0);
            var attrition = Math.round(ds.attrition || 0);
            var recovery = Math.round(ds.recovery || 0);
            return Math.max(0, Math.min(100, Math.round(
                Math.min(100, productive) * 0.4 +
                Math.max(0, 100 - corrosive * 3.5) * 0.2 +
                Math.max(0, 100 - (attrition - 4) * 6) * 0.2 +
                recovery * 0.2
            )));
        }

        // Safe-fallback chart-label localizer: returns the translation if resolvable,
        // otherwise the English fallback (never a raw i18n key).
        _cl(key, fallback) {
            try {
                if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                    var v = window.mySimulation.t(key);
                    if (v && v !== key) return v;
                }
            } catch (e) {}
            return fallback;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const productive = Math.round(ds.productive);
            const corrosive = Math.round(ds.corrosive);
            const attrition = Math.round(ds.attrition);
            const recovery = Math.round(ds.recovery);

            const passProductive = productive >= this.TARGET_PRODUCTIVE;
            const passAttrition = attrition <= this.TARGET_ATTRITION;
            const survived = passProductive && passAttrition;
            const renewable = recovery >= 55 && !ds.accelerationTrap;
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            let performanceKey = `grade_merged`;
            if (survived && renewable && corrosive < this.HEALTHY_CORROSIVE && composite >= 72) performanceKey = `grade_healthy`;
            else if (survived && renewable) performanceKey = `grade_renewable`;
            else if (survived && ds.accelerationTrap) performanceKey = `grade_trap`;
            else if (survived) performanceKey = `grade_fragile`;
            else if (productive > this.START_PRODUCTIVE + 8) performanceKey = `grade_improving`;
            const performance = T(performanceKey);

            const insights = [];
            if (survived && renewable && corrosive < this.HEALTHY_CORROSIVE) insights.push(window.mySimulation.t(`insight_healthy`));
            else if (survived && ds.accelerationTrap) insights.push(window.mySimulation.t(`insight_trap`));
            else if (survived) insights.push(window.mySimulation.t(`insight_fragile`));
            else insights.push(window.mySimulation.t(`insight_merged`));

            if (corrosive >= this.HEALTHY_CORROSIVE) insights.push(window.mySimulation.t(`insight_corrosive`));
            if (attrition > this.TARGET_ATTRITION) insights.push(window.mySimulation.t(`insight_attrition`));
            if (recovery < 40) insights.push(window.mySimulation.t(`insight_recovery`));
            if (survived && renewable && corrosive < this.HEALTHY_CORROSIVE && productive >= this.HEALTHY_PRODUCTIVE) insights.push(window.mySimulation.t(`insight_benchmark`));

            return {
                productive: productive,
                corrosive: corrosive,
                attrition: attrition,
                recovery: recovery,
                survived: survived,
                accelerationTrap: ds.accelerationTrap,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                merged: ds.merged,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var met = !!s.survived;
            var badge = met
                ? '<span class="energizesim-cm-badge energizesim-cm-yes">' + T('cm_board_met') + '</span>'
                : '<span class="energizesim-cm-badge energizesim-cm-no">' + T('cm_board_missed') + '</span>';
            var trapBadge = s.accelerationTrap
                ? '<span class="energizesim-cm-badge energizesim-cm-warn">' + T('cm_trap_badge') + '</span>'
                : '';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="energizesim-cm-metric"><span class="energizesim-cm-mv">' + Math.round(s.productive || 0) + '%</span><span class="energizesim-cm-ml">' + T('cm_m_productive') + '</span></div>'
                + '<div class="energizesim-cm-metric"><span class="energizesim-cm-mv">' + Math.round(s.corrosive || 0) + '%</span><span class="energizesim-cm-ml">' + T('cm_m_corrosive') + '</span></div>'
                + '<div class="energizesim-cm-metric"><span class="energizesim-cm-mv">' + Math.round(s.attrition || 0) + '%</span><span class="energizesim-cm-ml">' + T('cm_m_attrition') + '</span></div>'
                + '<div class="energizesim-cm-metric"><span class="energizesim-cm-mv">' + Math.round(s.recovery || 0) + '</span><span class="energizesim-cm-ml">' + T('cm_m_recovery') + '</span></div>';
            return ''
                + '<div class="energizesim-completion">'
                +   '<div class="energizesim-cm-head">'
                +     '<div class="energizesim-cm-score">' + score + '<span class="energizesim-cm-score-max">/100</span></div>'
                +     '<div class="energizesim-cm-grade">' + grade + ' ' + badge + trapBadge + '</div>'
                +   '</div>'
                +   '<div class="energizesim-cm-metrics">' + metrics + '</div>'
                +   '<div class="energizesim-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="energizesim-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.recovery < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_recovery`);
            if (ds.corrosive > 14 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_corrosive`);
            if (ds.trust < 35 && state.currentPeriod <= 2) return window.mySimulation.t(`hint_trust`);
            if (state.currentPeriod >= 3 && ds.productive < 48) return window.mySimulation.t(`hint_behind`);
            if (ds.attrition > this.TARGET_ATTRITION && state.currentPeriod >= 3) return window.mySimulation.t(`hint_attrition`);
            if (ds.productive >= this.TARGET_PRODUCTIVE && ds.attrition <= this.TARGET_ATTRITION && ds.recovery >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: `period`, label: `Quarter`, i18nKey: `col_round` },
